import{_ as a,a0 as d,w as p,s as u,ao as o,I as r,x as t,a1 as s,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"userdel 命令 - 從Linux系統中刪除用户賬户 | LCTT x X-CMD","titleTemplate":false,"description":"userdel 命令 - 從Linux系統中刪除用户賬户 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"userdel 命令 - 從Linux系統中刪除用户賬户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"userdel 命令 - 從Linux系統中刪除用户賬户 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/userdel Command - Delete User Account from Linux system","title":"userdel 命令 - 從Linux系統中刪除用户賬户","tag":"201402","desc":""},"relativePath":"201402/userdel Command - Delete User Account from Linux system.md","filePath":"[post].md"}'),i={name:"201402/userdel Command - Delete User Account from Linux system.md"};function m(x,e,g,f,T,L){const n=d("Link");return p(),u("div",null,[e[20]||(e[20]=o(`<h1 id="userdel-命令-從linux系統中刪除用户賬户" tabindex="-1">userdel 命令 - 從Linux系統中刪除用户賬户 <a class="header-anchor" href="#userdel-命令-從linux系統中刪除用户賬户" aria-label="Permalink to “userdel 命令 - 從Linux系統中刪除用户賬户”">​</a></h1><p>在服務器上維護用户就是添加、修改以及刪除用户。當一個用户出於某種原因不再需要登錄系統時，我們需要刪除此用户以避免安全漏洞。在Linux系統上，我們用 <strong>userdel</strong> 命令來刪除一個用户。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel-linux-command.jpg" alt=""></p><h3 id="userdel是什麼" tabindex="-1">userdel是什麼 <a class="header-anchor" href="#userdel是什麼" aria-label="Permalink to “userdel是什麼”">​</a></h3><p>userdel 是一個底層用於刪除用户的工具。在 Debian 上，我們通常會使用 deluser 命令。userdel 會查詢系統賬户文件，例如 <strong>/etc/password</strong> 和 <strong>/etc/group</strong>。那麼它會刪除所有和用户名相關的條目。在我們刪除它之前，用户名必須存在。</p><h3 id="如何使用userdel" tabindex="-1">如何使用userdel <a class="header-anchor" href="#如何使用userdel" aria-label="Permalink to “如何使用userdel”">​</a></h3><p>由於 userdel 會修改系統賬户文件，那麼我們<strong>需要root特權</strong>來運行它。不然我們會遇到一個報錯信息“<em>只有root權限才能執行這項操作</em>”或者類似的信息。在我們得到特權後，我們可以通過輸入 userdel 從你的控制台刪除用户。下面是一個默認使用 userdel 的樣例。</p><pre><code>$ sudo userdel pasadena
</code></pre><p>或者</p><pre><code># userdel pasadena
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_default.png" alt=""></p><p>正如你所見，我們不能沒有root權限而刪除用户 pasadena。當我們有權限時，系統不會給出錯誤信息，這意味着用户已經成功刪除。</p><h3 id="完全刪除用户家目錄" tabindex="-1">完全刪除用户家目錄 <a class="header-anchor" href="#完全刪除用户家目錄" aria-label="Permalink to “完全刪除用户家目錄”">​</a></h3><p>不帶選項使用 userdel，只會刪除用户。用户的家目錄將仍會在/home目錄下。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_home_folder.png" alt=""></p><p>當我們進入/home目錄時，我們仍舊可以看到ID 1002擁有 pasadena 文件夾。已創建的用户通常會有一個與用户名相同的組名。1002是 pasadena 用户名的 UID 和 pasadena 組名的 GID。</p><p>為了在刪除用户時完全刪除家目錄，我們可以使用 <strong>-r</strong> 選項。這個選項同樣會刪除用户的郵件池，如果存在的話。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_r.png" alt=""></p><h3 id="強制刪除一個用户" tabindex="-1">強制刪除一個用户 <a class="header-anchor" href="#強制刪除一個用户" aria-label="Permalink to “強制刪除一個用户”">​</a></h3><p>userdel 提供了 <strong>-f</strong> 選項來強制刪除用户。甚至當用户已經登入 Linux 系統時此選項仍舊生效。請看一下示例截圖。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_f.png" alt=""></p>`,21)),r("p",null,[e[1]||(e[1]=t("截圖的上面顯示用户 pasadena 已經登錄了系統。它被標記的進程",-1)),e[2]||(e[2]=r("strong",null,"6218",-1)),e[3]||(e[3]=t("是 SSHD 進程。而當我們用“",-1)),e[4]||(e[4]=r("strong",null,"userdel -f pasadena",-1)),e[5]||(e[5]=t("”只會顯示已經登錄的要被刪除的用户信息。命令本身已經成功。如果我們使用",-1)),s(n,{href:"http://linoxide.com/linux-command/13-cat-command-examples/"},{default:l(()=>[...e[0]||(e[0]=[t("cat 命令",-1)])]),_:1}),e[6]||(e[6]=t("查看",-1)),e[7]||(e[7]=r("strong",null,"/etc/passwd",-1)),e[8]||(e[8]=t("的內容，我們看不到到用户 pasadena 存在了。他的家目錄還存在但是所有者只能顯示為數字ID。",-1))]),e[21]||(e[21]=o('<p>有一件事我們必須瞭解，帶 <strong>-f</strong> 選項的 userdel <strong>不會斷開</strong> 該用户已有的 SSH 鏈接。因此，即使用户已經不存在，但實際上仍是登錄狀態，並且是活躍用户。但是當用户登出後不可再登錄，因為用户已經被刪除。</p><p>因此<strong>所以這個選項使用起來有些危險</strong>，因為它會使你的系統進入不一致的狀態。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>userdel 是一個 Linux 系統內部刪除用户的工具。userdel同樣是<strong>deluser</strong>命令的後端，這是一個用perl編寫的刪除用户的腳本。如往常一樣，你可以輸入<strong>man userdel</strong>來查看關於userdel命令的更多細節。</p><hr>',5)),r("p",null,[e[10]||(e[10]=t("via: ",-1)),s(n,{href:"http://linoxide.com/linux-command/linux-userdel-command/"},{default:l(()=>[...e[9]||(e[9]=[t("http://linoxide.com/linux-command/linux-userdel-command/",-1)])]),_:1})]),r("p",null,[e[13]||(e[13]=t("譯者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:l(()=>[...e[11]||(e[11]=[t("geekpi",-1)])]),_:1}),e[14]||(e[14]=t(" 校對：",-1)),s(n,{href:"https://github.com/carolinewuyan"},{default:l(()=>[...e[12]||(e[12]=[t("Caroline",-1)])]),_:1})]),r("p",null,[e[17]||(e[17]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原創翻譯，",-1)),s(n,{href:"http://linux.cn/"},{default:l(()=>[...e[16]||(e[16]=[t("Linux中國",-1)])]),_:1}),e[19]||(e[19]=t(" 榮譽推出",-1))])])}const b=a(i,[["render",m]]);export{D as __pageData,b as default};
